mapper.select:
SELECT ci.TREAD_CODE AS treadCode, SUM(IFNULL(cx.CLASS1_PLAN_QTY, 0) * IFNULL(ci.TREAD_SHOULDER_LENGTH, 0)) AS qty FROM T_CX_SCHEDULE_RESULT cx LEFT JOIN T_MDM_CONSTRUCTION_INFO ci ON cx.EMBRYO_CODE = ci.CONSTRUCTION_CODE AND (cx.BOM_DATA_VERSION = ci.CONSTRUCTION_VERSION OR (cx.BOM_DATA_VERSION IS NULL AND ci.CONSTRUCTION_VERSION IS NULL)) AND ci.IS_DELETE = 0 WHERE cx.FACTORY_CODE = #{factoryCode} AND cx.SCHEDULE_DATE = #{scheduleDate} AND ci.TREAD_CODE IN
#{treadCode}
GROUP BY ci.TREAD_CODE

SELECT ci.TREAD_CODE AS treadCode, SUM(IFNULL(cx.CLASS1_PLAN_QTY, 0) * IFNULL(ci.TREAD_SHOULDER_LENGTH, 0)) AS qty FROM T_CX_SCHEDULE_RESULT cx INNER JOIN T_MDM_CONSTRUCTION_INFO ci ON cx.EMBRYO_CODE = ci.CONSTRUCTION_CODE AND cx.CLASS1_RECIPE_NO = ci.CONSTRUCTION_VERSION AND ci.IS_DELETE = 0 WHERE cx.FACTORY_CODE = #{factoryCode} AND cx.SCHEDULE_DATE = #{scheduleDate} AND ci.TREAD_CODE IN
#{treadCode}
GROUP BY ci.TREAD_CODE

SELECT TREAD_CODE AS treadCode,
       SUM(IFNULL(CLASS3_PLAN_QTY, 0)) AS qty
FROM T_TM_SCHEDULE_RESULT
WHERE FACTORY_CODE = #{factoryCode}
  AND SCHEDULE_DATE = #{scheduleDate}
  AND TREAD_CODE IN

      #{treadCode}

GROUP BY TREAD_CODE
